/**
 * FILL `OJAD` ON CARDS MADE IN THE APP — the pipeline's own code, over the live data.
 *
 *     npx vite-node scripts/ojad-fill.ts             # what it would send
 *     npx vite-node scripts/ojad-fill.ts -- --apply  # send it
 *
 * Zach, 2026-10-24: *"i still don't see ojad filled automatically"*. `OJAD`
 * (decision 43) has only ever come from `tools/accent_sentence.py`, run on the
 * laptop over `build/hashigo.db` — which holds the IMPORTED cards. A card made in
 * the app lives in a device's OPFS, and its example sentence is generated by the
 * Worker into KV. So nothing reached them: on that date 20 of 20 app-made 単語
 * cards had no `OJAD`, all 18 漢検 cards among them. Nothing in the browser or the
 * Worker can run OpenJTalk, so this stays a laptop command.
 *
 * ─── HOW, AND WHY THIS SHAPE ────────────────────────────────────────────────
 *
 *   1. Copy `build/hashigo.db` to a scratch file. The real one is never written.
 *   2. Merge the freshest device payload into the copy with `mergeSync` — exactly
 *      what a device does — so the app-made cards and their values are there.
 *   3. File each missing card's example sentence from the Worker's KV into the
 *      copy (`storeDescriptorText`, as `cloud-generated-pull.ts` does).
 *   4. `extractSentences` → `tools/accent_sentence.py` → `loadMarks`, unchanged:
 *      the same cleaning, overrides and refusal rule (decision 8) the 3,711
 *      imported sentences went through.
 *   5. Send ONLY those `OJAD` values, from a sync slot of its own
 *      (`dev-ojad-fill`), with each card's clock moved to now and its flags copied
 *      from the freshest payload. Since e3254c5 a value merges by its card's clock,
 *      so these win, and no other field of those cards is in the payload to touch.
 *
 * The slot is CUMULATIVE: a run keeps what earlier runs sent, at the clocks they
 * sent them with, so a device that only ever sees this slot later still gets
 * every value. An edit he makes afterwards carries a newer clock and wins.
 *
 * Reads `VITE_MAILBOX_URL` / `VITE_MAILBOX_TOKEN` from `.env`, like
 * `cloud-generated-pull.ts`. Python is `.venv-accent`, like the original run.
 */
import { spawnSync } from "node:child_process";
import { copyFileSync, existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { gunzipSync } from "node:zlib";

import { extractSentences, loadMarks, type AnnotatedLine } from "../src/accent/marks.js";
import { generationIdentity, generationKey } from "../src/blobs/generation.js";
import { loadCard } from "../src/cards/index.js";
import { openDatabase } from "../src/db/index.js";
import { fieldWithRole } from "../src/fields/roles.js";
import {
  fieldGenerationRequest,
  resolveDescriptorText,
  storeDescriptorText,
  storeTextResolver,
  stripThinking,
} from "../src/generate/index.js";
import { mergeSync, type SyncPayload } from "../src/sync/index.js";

const SLOT = "dev-ojad-fill";
const apply = process.argv.includes("--apply");

if (existsSync(".env")) process.loadEnvFile(".env");
const base = (process.env["VITE_MAILBOX_URL"] ?? "").replace(/\/+$/, "");
const token = process.env["VITE_MAILBOX_TOKEN"] ?? "";
if (base === "" || token === "") {
  console.error("VITE_MAILBOX_URL and VITE_MAILBOX_TOKEN must be in .env");
  process.exit(2);
}
const headers = { Authorization: `Bearer ${token}` };

async function payloadOf(id: string): Promise<SyncPayload | null> {
  const response = await fetch(`${base}/sync/${encodeURIComponent(id)}`, { headers });
  if (!response.ok) return null;
  let bytes = Buffer.from(await response.arrayBuffer());
  if (bytes[0] === 0x1f && bytes[1] === 0x8b) bytes = gunzipSync(bytes);
  return JSON.parse(bytes.toString("utf8")) as SyncPayload;
}

// ── 1-2. the freshest device's view, merged into a scratch copy ─────────────
const listing = (await (await fetch(`${base}/sync/`, { headers })).json()) as {
  peers: { deviceId: string }[];
};
let freshest: SyncPayload | null = null;
for (const { deviceId } of listing.peers) {
  if (deviceId === SLOT) continue;
  const payload = await payloadOf(deviceId);
  if (payload !== null && (freshest === null || payload.archive.createdAt > freshest.archive.createdAt)) {
    freshest = payload;
  }
}
if (freshest === null) throw new Error("no device payload in the mailbox");
console.log(`freshest payload: ${freshest.archive.createdAt}`);

const scratchDir = mkdtempSync(join(tmpdir(), "ojad-fill-"));
const scratch = join(scratchDir, "hashigo.db");
copyFileSync("build/hashigo.db", scratch);
const db = openDatabase(scratch, { applySchema: false });

try {
  mergeSync(db, freshest);

  // ── 3. the targets, and their sentences from KV ──────────────────────────
  const localIds = new Set((freshest.archive.localCards ?? []).map((c) => c.id));
  const targets: { cardId: string; fieldId: string }[] = [];
  let missingSentence = 0;
  for (const cardId of localIds) {
    const card = loadCard(db, cardId);
    if (card?.template == null) continue;
    const marks = fieldWithRole(card.template.fields, "ojad");
    const source = card.template.fields.find((f) => f.id === marks?.sourceFieldId);
    if (marks === null || source === undefined) continue;
    const held = db
      .prepare("SELECT value FROM card_field_values WHERE card_id = ? AND field_id = ?")
      .get(cardId, marks.id) as { value: string } | undefined;
    if (held !== undefined && held.value.trim() !== "") continue;
    const request = fieldGenerationRequest(source, {
      fields: card.template.fields,
      values: card.values,
      resolveGenerated: storeTextResolver(db),
    });
    if (request === null) continue;
    if (resolveDescriptorText(db, request) === null) {
      const key = generationKey(
        generationIdentity({
          kind: request.kind,
          text: request.text,
          voice: request.voice,
          lang: request.lang,
          options: request.options,
        }),
      );
      const response = await fetch(`${base}/generated/${encodeURIComponent(key)}`, { headers });
      const record = response.ok ? ((await response.json()) as { output?: string }) : null;
      if (record?.output === undefined || record.output === "") {
        missingSentence += 1;
        console.log(`  ${card.name}: no example sentence generated yet — skipped`);
        continue;
      }
      storeDescriptorText(db, request, stripThinking(record.output));
    }
    targets.push({ cardId, fieldId: marks.id });
  }
  console.log(`${targets.length} card(s) to fill · ${missingSentence} without a sentence yet`);
  if (targets.length === 0 && !apply) process.exit(0);

  // ── 4. the pipeline, unchanged ───────────────────────────────────────────
  const wanted = new Set(targets.map((t) => t.cardId));
  const rows = extractSentences(db).clean.filter((row) => wanted.has(row.cardId));
  const sentencesFile = join(scratchDir, "sentences.txt");
  const marksFile = join(scratchDir, "marks.jsonl");
  writeFileSync(sentencesFile, rows.map((r) => r.sentence).join("\n") + "\n", "utf8");
  const python = spawnSync(
    ".venv-accent/Scripts/python",
    ["tools/accent_sentence.py", "--in", sentencesFile, "--out", marksFile],
    { stdio: "inherit" },
  );
  if (python.status !== 0) throw new Error("tools/accent_sentence.py failed");
  const lines = readFileSync(marksFile, "utf8")
    .split("\n")
    .filter((l) => l.trim() !== "")
    .map((l) => JSON.parse(l) as AnnotatedLine);
  const report = loadMarks(db, lines, rows);
  console.log(
    `annotated: ${report.written} · refused by the analyser (left empty, decision 8): ${report.unannotated}`,
  );

  // ── 5. the payload: only OJAD values, with a moved clock ─────────────────
  const now = new Date().toISOString();
  const previous = await payloadOf(SLOT);
  const flags = new Map(freshest.cardFlags.map((f) => [f.cardId, f]));
  const values = new Map<string, { cardId: string; fieldId: string; value: string }>();
  const clocks = new Map<string, string>();
  for (const v of previous?.archive.fieldValues ?? []) values.set(`${v.cardId}|${v.fieldId}`, v);
  for (const f of previous?.cardFlags ?? []) clocks.set(f.cardId, f.updatedAt);
  for (const row of rows) {
    const got = db
      .prepare("SELECT value FROM card_field_values WHERE card_id = ? AND field_id = ?")
      .get(row.cardId, row.fieldId) as { value: string } | undefined;
    if (got === undefined || got.value.trim() === "") continue;
    values.set(`${row.cardId}|${row.fieldId}`, { cardId: row.cardId, fieldId: row.fieldId, value: got.value });
    clocks.set(row.cardId, now);
    const name = loadCard(db, row.cardId)?.name ?? row.cardId;
    console.log(`  ${name}: ${got.value}`);
  }
  const fieldValues = [...values.values()];
  const cardFlags = [...clocks.entries()]
    .filter(([cardId]) => flags.has(cardId))
    .map(([cardId, updatedAt]) => ({ ...flags.get(cardId)!, updatedAt }));
  const payload: SyncPayload = {
    syncVersion: freshest.syncVersion,
    archive: {
      archiveVersion: freshest.archive.archiveVersion,
      schemaVersion: freshest.archive.schemaVersion,
      createdAt: now,
      reviews: [],
      trackState: [],
      localFields: [],
      localCards: [],
      templates: [],
      fieldValues,
      settings: [],
      cardState: [],
      counts: {
        reviews: 0,
        trackState: 0,
        localFields: 0,
        localCards: 0,
        templates: 0,
        fieldValues: fieldValues.length,
        settings: 0,
        cardState: 0,
      },
    },
    cardFlags,
    deckFlags: [],
    // `voicesCarried` left out ON PURPOSE: absent means "this payload says nothing
    // about voices", so the merge sets flags without touching a card's voice.
    retiredClips: [],
  };

  // ── SELF-CHECK: merge it into a fresh copy exactly as a device would ─────
  // Refuses to send unless every value lands and NOTHING ELSE on those cards
  // moved — the payload is hand-built, so this is the test that it is shaped
  // the way `mergeSync` reads it.
  const checkFile = join(scratchDir, "check.db");
  copyFileSync("build/hashigo.db", checkFile);
  const check = openDatabase(checkFile, { applySchema: false });
  try {
    mergeSync(check, freshest);
    const snapshot = (): Map<string, string> =>
      new Map(
        (
          check
            .prepare(
              `SELECT card_id || '|' || field_id AS k, value FROM card_field_values
                WHERE card_id IN (${fieldValues.map(() => "?").join(",") || "''"})`,
            )
            .all(...fieldValues.map((v) => v.cardId)) as { k: string; value: string }[]
        ).map((r) => [r.k, r.value]),
      );
    const before = snapshot();
    mergeSync(check, payload);
    const after = snapshot();
    const landed = fieldValues.filter((v) => after.get(`${v.cardId}|${v.fieldId}`) === v.value).length;
    const ojadKeys = new Set(fieldValues.map((v) => `${v.cardId}|${v.fieldId}`));
    const touched = [...before].filter(([k, value]) => !ojadKeys.has(k) && after.get(k) !== value);
    console.log(`self-check: ${landed}/${fieldValues.length} landed · ${touched.length} other value(s) changed`);
    if (landed !== fieldValues.length || touched.length > 0) {
      throw new Error("self-check failed — nothing sent");
    }
  } finally {
    check.close();
  }

  if (!apply) {
    console.log(`DRY RUN — would send ${fieldValues.length} value(s) from ${SLOT}. Add --apply to send.`);
  } else {
    const response = await fetch(`${base}/sync/${SLOT}`, {
      method: "PUT",
      headers: { ...headers, "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    console.log(`sent ${fieldValues.length} value(s) from ${SLOT}: ${response.status} ${await response.text()}`);
  }
} finally {
  db.close();
  rmSync(scratchDir, { recursive: true, force: true });
}
